import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import ControlPanel from './ControlPanel';
import {
  VisualizationContainer,
  ElementsContainer,
  ElementBox,
  IndexLabel,
  StatusMessage,
  DataStructureContainer,
  SectionTitle,
  DataStructureBox,
  ResultsContainer,
  ResultItem
} from './VisualizationStyles';

// Custom styled components specific to this visualization
const StackItem = styled.div`
  padding: 8px 0;
  background-color: #f5f5f5;
  border: 1px solid #e0e0e0;
  border-radius: var(--border-radius);
  text-align: center;
  font-weight: 500;
  animation: ${props => props.isNew ? 'fadeIn 0.5s ease' : 'none'};
  
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
  }
`;

const EmptyStack = styled.div`
  padding: 8px 0;
  text-align: center;
  color: var(--text-secondary);
  font-style: italic;
`;

const ExampleSection = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
`;

const ExampleButton = styled.button`
  padding: 0.5rem 1rem;
  background: ${props => props.isSelected ? 'var(--primary)' : '#f5f5f5'};
  color: ${props => props.isSelected ? 'white' : 'var(--text-primary)'};
  border: 1px solid ${props => props.isSelected ? 'var(--primary)' : '#e0e0e0'};
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.9rem;
  
  &:hover {
    background: ${props => props.isSelected ? 'var(--primary-dark)' : '#e0e0e0'};
  }
`;

const DEFAULT_STRING = "({[]})";
const EXAMPLES = [
  { label: "Valid 1", value: "({[]})" },
  { label: "Valid 2", value: "()[]{}" },
  { label: "Invalid 1", value: "([)]" },
  { label: "Invalid 2", value: "(]" },
  { label: "Invalid 3", value: "{{{" }
];

// Helper function to check if two characters form a valid pair
const isValidPair = (open, close) => {
  return (
    (open === '(' && close === ')') ||
    (open === '{' && close === '}') ||
    (open === '[' && close === ']')
  );
};

// Helper function to check if a character is an opening bracket
const isOpenBracket = (char) => {
  return char === '(' || char === '{' || char === '[';
};

const ValidParenthesesVisualization = () => {
  const [input, setInput] = useState(DEFAULT_STRING);
  const [currentIndex, setCurrentIndex] = useState(-1);
  const [stack, setStack] = useState([]);
  const [isRunning, setIsRunning] = useState(false);
  const [speed, setSpeed] = useState(1000); // in milliseconds
  const [invalidIndex, setInvalidIndex] = useState(null);
  const [processedIndices, setProcessedIndices] = useState([]);
  const [message, setMessage] = useState({ text: 'Click "Start" to begin the visualization.', type: 'info' });
  const [result, setResult] = useState(null);
  const [selectedExample, setSelectedExample] = useState(0);
  
  const reset = () => {
    setCurrentIndex(-1);
    setStack([]);
    setIsRunning(false);
    setInvalidIndex(null);
    setProcessedIndices([]);
    setMessage({ text: 'Click "Start" to begin the visualization.', type: 'info' });
    setResult(null);
  };
  
  const start = () => {
    reset();
    setIsRunning(true);
    setCurrentIndex(0);
  };
  
  const nextStep = () => {
    if (currentIndex < input.length && result === null) {
      processNextChar();
    }
  };
  
  const prevStep = () => {
    // Not implementing back functionality for simplicity
  };
  
  const handleInputChange = (e) => {
    setInput(e.target.value);
    setSelectedExample(-1); // Deselect any example
    reset();
  };
  
  const selectExample = (index) => {
    setSelectedExample(index);
    setInput(EXAMPLES[index].value);
    reset();
  };
  
  const checkBalance = (str) => {
    const stack = [];
    
    for (let char of str) {
      if (isOpenBracket(char)) {
        stack.push(char);
      } else {
        if (stack.length === 0) {
          return false;
        }
        
        const lastBracket = stack.pop();
        if (!isValidPair(lastBracket, char)) {
          return false;
        }
      }
    }
    
    return stack.length === 0;
  };
  
  const processNextChar = () => {
    if (currentIndex >= input.length) return;
    
    const currentChar = input[currentIndex];
    
    if (isOpenBracket(currentChar)) {
      // Push to stack if it's an opening bracket
      const newStack = [...stack, currentChar];
      setStack(newStack);
      setMessage({ 
        text: `Found opening bracket '${currentChar}' at index ${currentIndex}, pushing to stack.`, 
        type: 'info' 
      });
      setProcessedIndices([...processedIndices, currentIndex]);
      
      if (currentIndex === input.length - 1) {
        // End of string but we still have items in stack
        setResult(false);
        setMessage({ 
          text: `Reached end of string, but stack is not empty. The string is invalid.`, 
          type: 'error' 
        });
      } else {
        // Move to next character
        setTimeout(() => {
          setCurrentIndex(currentIndex + 1);
        }, speed);
      }
    } else {
      // Current char is a closing bracket
      if (stack.length === 0) {
        // No matching opening bracket
        setInvalidIndex(currentIndex);
        setResult(false);
        setMessage({ 
          text: `Found closing bracket '${currentChar}' at index ${currentIndex} with no matching opening bracket. The string is invalid.`, 
          type: 'error' 
        });
      } else {
        // Check if it matches the top of the stack
        const top = stack[stack.length - 1];
        if (isValidPair(top, currentChar)) {
          // Valid pair, pop the stack
          const newStack = stack.slice(0, -1);
          setStack(newStack);
          setProcessedIndices([...processedIndices, currentIndex]);
          setMessage({ 
            text: `Found closing bracket '${currentChar}' at index ${currentIndex} matching with '${top}'. Popping from stack.`, 
            type: 'success' 
          });
          
          // Check if we've reached the end
          if (currentIndex === input.length - 1) {
            // End of string, check if stack is empty
            if (newStack.length === 0) {
              setResult(true);
              setMessage({ 
                text: `Reached end of string with an empty stack. The string is valid!`, 
                type: 'success' 
              });
            } else {
              setResult(false);
              setMessage({ 
                text: `Reached end of string, but stack is not empty. The string is invalid.`, 
                type: 'error' 
              });
            }
          } else {
            // Move to next character
            setTimeout(() => {
              setCurrentIndex(currentIndex + 1);
            }, speed);
          }
        } else {
          // Invalid pair
          setInvalidIndex(currentIndex);
          setResult(false);
          setMessage({ 
            text: `Found closing bracket '${currentChar}' at index ${currentIndex} not matching with '${top}'. The string is invalid.`, 
            type: 'error' 
          });
        }
      }
    }
  };
  
  // Process steps automatically when running
  useEffect(() => {
    if (isRunning && currentIndex >= 0 && currentIndex < input.length && result === null) {
      processNextChar();
    } else if (isRunning && (currentIndex >= input.length || result !== null)) {
      setIsRunning(false);
    }
  }, [currentIndex, isRunning]);
  
  // Pre-validation for immediate feedback
  const isCurrentInputValid = checkBalance(input);
  
  return (
    <VisualizationContainer>
      <ControlPanel
        onStart={start}
        onNext={nextStep}
        onPrev={prevStep}
        onReset={reset}
        isRunning={isRunning}
        canGoNext={currentIndex < input.length && result === null}
        canGoPrev={false} // Not implementing back functionality for simplicity
        speed={speed}
        onSpeedChange={setSpeed}
        showPrev={false}
        customInputProps={{
          label: "Input String",
          value: input,
          onChange: handleInputChange,
          disabled: isRunning
        }}
      />
      
      <ExampleSection>
        <div style={{ marginRight: '0.5rem' }}>Examples:</div>
        {EXAMPLES.map((example, index) => (
          <ExampleButton
            key={index}
            isSelected={selectedExample === index}
            onClick={() => selectExample(index)}
            disabled={isRunning}
          >
            {example.label}
          </ExampleButton>
        ))}
      </ExampleSection>
      
      {!isRunning && currentIndex === -1 && (
        <StatusMessage type={isCurrentInputValid ? 'info' : 'warning'}>
          Input is {isCurrentInputValid ? 'valid' : 'invalid'}. Press Start to see step by step analysis.
        </StatusMessage>
      )}
      
      <ElementsContainer>
        {input.split('').map((char, index) => (
          <ElementBox 
            key={index}
            isPrimary={index === currentIndex}
            isSuccess={processedIndices.includes(index)}
            isError={index === invalidIndex}
            isBold={true}
          >
            <IndexLabel>{index}</IndexLabel>
            {char}
          </ElementBox>
        ))}
      </ElementsContainer>
      
      <DataStructureContainer>
        <SectionTitle>Stack:</SectionTitle>
        <DataStructureBox direction="column-reverse" minHeight="150px">
          {stack.length === 0 ? (
            <EmptyStack>Empty Stack</EmptyStack>
          ) : (
            stack.map((item, index) => (
              <StackItem key={index} isNew={index === stack.length - 1}>
                {item}
              </StackItem>
            ))
          )}
        </DataStructureBox>
      </DataStructureContainer>
      
      {(isRunning || currentIndex !== -1) && (
        <StatusMessage type={message.type}>
          {message.text}
        </StatusMessage>
      )}
      
      {result !== null && (
        <ResultsContainer>
          <ResultItem>
            <strong>Final Result:</strong> The string is {result ? 'valid' : 'invalid'}.
          </ResultItem>
        </ResultsContainer>
      )}
    </VisualizationContainer>
  );
};

export default ValidParenthesesVisualization; 